def transform(grid):
    R,C=len(grid),len(grid[0]); out=[row[:] for row in grid]
    left={r for r in range(R) if grid[r][0]==1}; right={r for r in range(R) if grid[r][C-1]==1}
    top={c for c in range(C) if grid[0][c]==1}; bottom={c for c in range(C) if grid[R-1][c]==1}
    rows=left&right; cols=top&bottom
    for r in rows:
        for c in range(C): out[r][c]=1
    for c in cols:
        for r in range(R): out[r][c]=1
    seen=set()
    for r in range(R):
      for c in range(C):
        if grid[r][c]!=2 or (r,c) in seen: continue
        stack=[(r,c)]; seen.add((r,c)); comp=[]
        while stack:
          y,x=stack.pop(); comp.append((y,x))
          for yy,xx in ((y-1,x),(y+1,x),(y,x-1),(y,x+1),(y-1,x-1),(y-1,x+1),(y+1,x-1),(y+1,x+1)):
            if 0<=yy<R and 0<=xx<C and grid[yy][xx]==2 and (yy,xx) not in seen: seen.add((yy,xx)); stack.append((yy,xx))
        if any(y in rows or x in cols for y,x in comp):
          for y,x in comp: out[y][x]=1
    return out
